-- Update edge_version for v3 engines
UPDATE	job_new.engine
SET 		edge_version = 3
WHERE 	(
					LOWER(engine_name) LIKE '%v3%' 
					OR LOWER(engine_description) LIKE '%v3%' 
					OR LOWER(engine_alias_name) LIKE '%v3%' 
					OR LOWER(engine_alias_description) LIKE '%v3%' 
				)
		AND edge_version IS NULL;

-- Update engines single job and tdo templates, copy from US-PROD
-- Machinebox - Facebox Similarity V3
UPDATE 	job_new.engine 
SET 		single_engine_tdo_job_json = '{"template": "{\n  \"targetId\":{{#if TARGET_ID}} \"{{{TARGET_ID}}}\" {{else}} \"{{{TDO_ID}}}\" {{/if}},\n  {{#if notificationUri}} \"notificationUris\":[\"{{{notificationUri}}}\"], {{/if}}\n  {{#if clusterId}} \"clusterId\":\"{{{clusterId}}}\", {{/if}}\n  \"tasks\":[\n    {\n      \"engineId\":\"9e611ad7-2d3b-48f6-a51b-0a1ba40fe255\",\n      \"payload\":{\n        \"url\":\"{{{UPLOAD_URL}}}\"\n      },\n      \"executionPreferences\":{\n        {{#if priority}} \"priority\":{{{priority}}} {{/if}}\n      },\n      \"ioFolders\":[\n        {\n          \"referenceId\":\"wsa-output\",\n          \"mode\":\"stream\",\n          \"type\":\"output\"\n        }\n      ]\n    },\n    {\n      \"engineId\":\"8bdb0e3b-ff28-4f6e-a3ba-887bd06e6440\",\n      \"payload\":{\n        {{#if inputIsImage}}\n          \"ffmpegTemplate\":\"rawchunk\"\n        {{else}}\n          \"ffmpegTemplate\":\"frame\",\n          \"customFFMPEGProperties\":{\n            \"framesPerSecond\":{{#if framesPerSecond}} \"{{{framesPerSecond}}}\" {{else}} \"1\" {{/if}}\n          }\n        {{/if}}\n      },\n      \"executionPreferences\":{\n        {{#if priority}} \"priority\":{{{priority}}} {{/if}}\n      },\n      \"ioFolders\":[\n        {\n          \"referenceId\":\"si-input\",\n          \"mode\":\"stream\",\n          \"type\":\"input\"\n        },\n        {\n          \"referenceId\":\"si-output\",\n          \"mode\":\"chunk\",\n          \"type\":\"output\"\n        }\n      ]\n    },\n    {\n      \"engineId\":\"{{{ENGINE_ID}}}\",\n      \"payload\":{\n        {{#if minConfidence}} \"minConfidence\":{{{minConfidence}}}, {{/if}}\n        {{#if jitters}} \"jitters\":\"{{{jitters}}}\", {{/if}}\n        {{#if detector}} \"detector\":\"{{{detector}}}\", {{/if}}\n        {{#if libraryEngineModelId}} \"libraryEngineModelId\":\"{{{libraryEngineModelId}}}\", {{/if}}\n        \"libraryId\":\"{{{libraryId}}}\"\n      },\n      \"executionPreferences\":{\n        {{#if priority}} \"priority\":{{{priority}}}, {{/if}}\n        \"parentCompleteBeforeStarting\":true\n      },\n      \"ioFolders\":[\n        {\n          \"referenceId\":\"engine-input\",\n          \"mode\":\"chunk\",\n          \"type\":\"input\"\n        },\n        {\n          \"referenceId\":\"engine-output\",\n          \"mode\":\"chunk\",\n          \"type\":\"output\"\n        }\n      ]\n    }\n    ,\n    {\n      \"engineId\":\"8eccf9cc-6b6d-4d7d-8cb3-7ebf4950c5f3\",\n      \"executionPreferences\":{\n        {{#if priority}} \"priority\":{{{priority}}}, {{/if}}\n        \"parentCompleteBeforeStarting\":true\n      },\n      \"ioFolders\":[\n        {\n          \"referenceId\":\"ow-input\",\n          \"mode\":\"chunk\",\n          \"type\":\"input\"\n        }\n      ]\n    }\n  ],\n  \"routes\":[\n    {\n      \"parentIoFolderReferenceId\":\"wsa-output\",\n      \"childIoFolderReferenceId\":\"si-input\"\n    },\n    {\n      \"parentIoFolderReferenceId\":\"si-output\",\n      \"childIoFolderReferenceId\":\"engine-input\"\n    },\n    {\n      \"parentIoFolderReferenceId\":\"engine-output\",\n      \"childIoFolderReferenceId\":\"ow-input\"\n    }\n  ]\n}\n", "templateLanguage": "Handlebars"}'
WHERE 	engine_id = 'ab682a42-ffdb-40cd-a8f7-432905f0a5a1'
		AND single_engine_tdo_job_json IS NULL;

