-- Pangeanic - German to English V3
UPDATE 	job_new.engine 
SET 		single_engine_tdo_job_json = '{"template": "{\n   \"targetId\":{{#if TARGET_ID}} \"{{{TARGET_ID}}}\" {{else}} \"{{{TDO_ID}}}\" {{/if}},\n  {{#if notificationUri}} \"notificationUris\":[\"{{{notificationUri}}}\"], {{/if}}\n  {{#if clusterId}} \"clusterId\":\"{{{clusterId}}}\", {{/if}}\n{{#if vtnMode}} \"tasks\": [\n     {\n       \"engineId\": \"{{ENGINE_ID}}\",\n       \"payload\":{\n         \"url\":\"{{{UPLOAD_URL}}}\" \n       },\n       \"ioFolders\":[\n         {\n           \"referenceId\": \"engineOutputFolder\",\n           \"mode\": \"chunk\",\n           \"type\": \"output\"\n         }\n       ]\n     },\n     {\n       \"engineId\": \"8eccf9cc-6b6d-4d7d-8cb3-7ebf4950c5f3\",\n       \"ioFolders\": [\n         {\n           \"referenceId\": \"owInputFolder\",\n           \"mode\": \"chunk\",\n           \"type\": \"input\"\n         } \n       ]\n     }\n   ],\n   \"routes\": [\n     {\n       \"parentIoFolderReferenceId\": \"engineOutputFolder\",\n       \"childIoFolderReferenceId\": \"owInputFolder\"\n     } \n   ]\n{{else}}\"tasks\": [\n     {\n       \"engineId\": \"{{ENGINE_ID}}\",\n       \"payload\":{}\n      }\n   ],\n   \"routes\": []\n{{/if}} \n}", "templateLanguage": "Handlebars"}'
WHERE 	engine_id = 'cbd5fc84-781a-4e45-bdac-c8b4e9e1354f'
		AND single_engine_tdo_job_json IS NULL;

